        *{box-sizing:border-box;margin:0;padding:0}body{min-height:100vh;background:#fff;color:#111;font-family:'Segoe UI',sans-serif}.page{width:100%;min-height:100vh;margin:0;padding:6px 48px 40px;position:relative}.profile{width:min(1104px,100%);display:grid;grid-template-columns:356px 1fr;gap:34px;margin:24px auto 0}.panel{background:#fff;border:1px solid #eee2b7;border-radius:22px;padding:26px;box-shadow:0 12px 30px #0000000d}.sidebar{text-align:center;align-self:start}.avatar{width:140px;height:140px;border-radius:50%;overflow:hidden;margin:0 auto 18px;border:2px solid #f3c547}.avatar img{width:100%;height:100%;object-fit:cover}.sidebar h1{font-size:22px;margin:0 0 8px;color:#111}.role,.rating,.price{color:#c99208}.actions{display:grid;gap:10px;margin-top:22px}.btn{border:0;border-radius:11px;padding:12px;font-size:12px;font-weight:700;cursor:pointer;text-decoration:none;background:#f3c547;color:#111}.btn.outline{background:#fff;border:1px solid #d9b83d;color:#c99208}.details{display:grid;gap:20px}.panel h2{margin:0 0 12px;font-size:18px;color:#111}.panel p{color:#69737e;line-height:1.65}.services{display:flex;flex-wrap:wrap;gap:9px}.service{padding:8px 13px;border-radius:999px;background:#fff5c9;color:#b07c00;font-size:13px}.packages,.gallery{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:14px}.package{position:relative;border:1px solid #eadcae;border-radius:15px;padding:18px}.package h3{margin:0 0 8px;color:#111}.package ul{padding-left:18px;color:#69737e;line-height:1.7}.featured{border:2px solid #d4a017}.tag{position:absolute;right:10px;top:10px;font-size:10px;background:#f3c547;padding:4px 8px;border-radius:999px}.gallery img,.gallery video{width:100%;height:150px;object-fit:cover;border-radius:12px}.review{border-top:1px solid #eee2b7;padding:13px 0}.review:first-child{border-top:0}.review p{margin:6px 0}.modal{display:none;position:fixed;inset:0;z-index:1000;background:#0007;align-items:center;justify-content:center;padding:20px}.modal.open{display:flex}.modal form{width:min(424px,100%);max-height:90vh;overflow:auto}.modal h2{font-size:18px}.modal label{display:block;font-size:11px;letter-spacing:.4px;font-weight:700;color:#69737e;margin-top:12px}.modal input,.modal textarea,.modal select{width:100%;box-sizing:border-box;padding:10px;border:1px solid #eadcae;border-radius:9px;margin-top:5px;font:inherit;font-size:12px}.modal textarea{min-height:58px;resize:vertical}.custom-booking form{padding:20px;border-radius:24px}.custom-booking .modal-header{display:flex;justify-content:space-between;align-items:start;padding-bottom:12px;border-bottom:1px solid #eee}.custom-booking .modal-header p{margin:5px 0 0;font-size:12px;color:#69737e}.custom-booking .modal-close{border:0;background:transparent;font-size:22px;color:#666;cursor:pointer}.custom-booking .field-row{display:grid;grid-template-columns:1fr 1fr;gap:12px}.custom-booking .modal-actions{margin-top:18px}.modal-actions{display:flex;gap:10px;margin-top:18px}.modal-actions .btn{flex:1}@media(max-width:800px){.page{width:100%;padding:6px 18px 30px}.profile{grid-template-columns:1fr}}@media(max-width:480px){.custom-booking .field-row{grid-template-columns:1fr}}
