    <div class="profile"><aside class="panel sidebar"><div class="avatar"><img src="{{ asset('images/userui/logo.png') }}" alt="{{ $coordinator->full_name }}"></div><h1>{{ $coordinator->full_name }}</h1><div class="role">{{ $coordinator->business_name ?: 'Professional Event Coordinator' }}</div><div class="rating">★★★★★ {{ $avgRating ? number_format($avgRating, 1) : '4.9' }}</div><div class="actions"><button class="btn" type="button" onclick="document.getElementById('packageModal').classList.add('open')">Book a Package</button><button class="btn outline" type="button" onclick="document.getElementById('customModal').classList.add('open')">Custom Event Booking</button><a class="btn outline" href="{{ route('your.messages', ['user_id' => $coordinator->user_id]) }}">Message</a></div></aside><main class="details"><section class="panel"><h2>About Me</h2><p>{!! nl2br(e($profile->about ?? $coordinator->business_address ?? 'Professional event coordinator with extensive experience in managing all types of events.')) !!}</p></section><section class="panel"><h2>Services Offered</h2><div class="services">@foreach($services as $service)<span class="service">{{ $service }}</span>@endforeach</div></section><section class="panel"><h2>Event Packages</h2>@if(count($packages) === 0)<p>This coordinator has not added package offerings yet.</p>@else<div class="packages">@foreach($packages as $package)<article class="package {{ $package->is_featured ? 'featured' : '' }}">@if($package->is_featured)<span class="tag">FEATURED</span>@endif<h3>{{ $package->name }}</h3><strong class="price">₱{{ number_format((float)$package->price, 2) }}</strong><p>{{ $package->description }}</p><ul>@foreach(array_filter(array_map('trim', explode('|', $package->inclusions ?? ''))) as $inclusion)<li>{{ $inclusion }}</li>@endforeach</ul><button class="btn" type="button" onclick="openPackage(@js($package->name))">Book This Package</button></article>@endforeach</div>@endif</section><section class="panel"><h2>Gallery</h2>@if(count($gallery) === 0)<p>No gallery items yet.</p>@else<div class="gallery">@foreach($gallery as $item)<div>@if($item->type === 'video')<video src="{{ $item->url }}" controls></video>@else<img src="{{ $item->url }}" alt="{{ $item->caption }}">@endif</div>@endforeach</div>@endif</section><section class="panel"><h2>Customer Reviews ({{ count($reviews) }})</h2>@forelse($reviews as $review)<article class="review"><strong>{{ $review->reviewer_name ?? 'Anonymous' }}</strong><span class="rating">{{ str_repeat('★', (int)$review->rating) }}</span><p>{{ $review->comment ?? '' }}</p><small>{{ $review->created_at }}</small></article>@empty<p>No reviews yet.</p>@endforelse</section></main></div>
