    <div class="modal custom-booking" id="customModal"><form class="panel" method="POST" action="{{ route('coordinators.custom-booking', $coordinator->user_id) }}">@csrf<div class="modal-header"><div><h2>Custom Event Booking</h2><p>Tell the coordinator about your dream event.</p></div><button class="modal-close" type="button" onclick="closeModals()" aria-label="Close">&times;</button></div><div class="field"><label>Event Type *</label><input name="event_type" placeholder="e.g. Wedding, Birthday, Corporate" required></div><div class="field"><label>Event Date *</label><input type="date" name="event_date" required></div><div class="field-row"><div class="field"><label>Venue Preference (Optional)</label><input name="venue_preference" placeholder="e.g. Beach resort, Garden"></div><div class="field"><label>Number of Guests</label><input type="number" name="guest_count" min="1" placeholder="e.g. 100"></div></div><div class="field-row"><div class="field"><label>Event Theme</label><input name="theme" placeholder="e.g. Rustic, Garden"></div><div class="field"><label>Budget (₱)</label><input type="number" name="budget" min="0" placeholder="e.g. 100000"></div></div><div class="field"><label>Required Services</label><input name="required_services" placeholder="e.g. Catering, Photography"></div><div class="field"><label>Special Requests</label><textarea name="special_requests" placeholder="Any special requests..."></textarea></div><div class="field"><label>Additional Notes</label><textarea name="additional_notes" placeholder="Anything else we should know?"></textarea></div><div class="modal-actions"><button class="btn outline" type="button" onclick="closeModals()">Cancel</button><button class="btn" type="submit">Send Request</button></div></form></div><script>function closeModals(){document.querySelectorAll('.modal').forEach(modal=>modal.classList.remove('open'));}function openPackage(name){document.getElementById('packageSelect').value=name;document.getElementById('packageModal').classList.add('open');}</script></body></html>